(function(root){'use strict';
const gates=[['structure','Structural checks'],['authorship','AI authorship check'],['similarity','Similarity'],['reference','Reference verification'],['quality','Quality review'],['anticheat','Anti-cheat probe'],['difficulty','Difficulty probe'],['audit','Run audit']];
const states=['pending','running','passed','task-failure','infra-failure'];
function validate(d,history=[]){const errors=[];if(!/^[a-z0-9]+(-[a-z0-9]+){0,2}$/.test(d.slug||''))errors.push('Enter a valid task slug of at most three lowercase kebab-case words.');if(!Number.isInteger(+d.revision)||+d.revision<1)errors.push('Revision must be a positive integer.');if(!['draft','submitted'].includes(d.submission))errors.push('Choose draft or submitted.');if(!['pending','approved','rejected'].includes(d.decision))errors.push('Choose a human-review state.');for(const [id,label]of gates)if(!states.includes(d.gates?.[id]))errors.push('Invalid gate state: '+label);if(d.conflict?.trim())errors.push('Known conflict recorded: discuss it and obtain explicit user permission before a conflicting action.');
if(d.submission==='submitted'){if(!/^[a-f0-9]{64}$/.test(d.archiveHash||''))errors.push('Select the exact submitted ZIP to record its SHA-256 hash.');if(!d.receipt?.trim()||!d.submittedAt)errors.push('Record the platform receipt/reference and submission date.');}
const same=history.filter(x=>x.slug===d.slug&&+x.revision===+d.revision),prior=history.filter(x=>x.slug===d.slug&&+x.revision<+d.revision),last=same.at(-1);
if(last?.archiveHash&&d.archiveHash&&last.archiveHash!==d.archiveHash)errors.push('Changed ZIP: create a new revision instead of rewriting this revision.');
if(d.archiveHash&&history.some(x=>x.archiveHash===d.archiveHash&&(x.slug!==d.slug||+x.revision!==+d.revision)))errors.push('Unchanged archive already recorded for another task/revision. Identical resubmissions are blocked by the project.');
if(+d.revision>1&&!d.changes?.trim())errors.push('Describe substantive changes for this revision; cosmetic rebuilds are prohibited.');if(prior.length&&!d.changes?.trim())errors.push('Record the revision changes.');
if(d.decision==='approved'){if(d.submission!=='submitted'||gates.some(([id])=>d.gates[id]!=='passed'))errors.push('Approval can only be recorded after submission and all automated gates are reported passed.');if(!d.approvedAt||!d.approvalEvidence?.trim())errors.push('Approval needs a date and a platform evidence reference.');}
if(d.decision==='rejected'&&!d.rejection?.trim())errors.push('Record the reviewer’s written rejection reason.');
if(d.paid&&(d.decision!=='approved'||!d.paidAt||!d.paymentEvidence?.trim()))errors.push('Payment needs recorded approval, payment date, and payment evidence.');
if(d.submittedAt&&d.approvedAt&&d.approvedAt<d.submittedAt)errors.push('Approval date cannot precede submission.');if(d.approvedAt&&d.paidAt&&d.paidAt<d.approvedAt)errors.push('Payment date cannot precede approval.');
if(d.attempts!==''&&(!Number.isInteger(+d.attempts)||+d.attempts<0||+d.attempts>8))errors.push('Difficulty successes must be an integer from 0 to 8.');return [...new Set(errors)];}
function payout(d){return d.decision==='approved'?{amount:300,currency:'USD',state:d.paid?'paid (self-reported)':'recorded at approval; normal cycle unspecified'}:{amount:0,currency:'USD',state:'no approval recorded'};}
function normalize(d){if(!d||typeof d!=='object'||Array.isArray(d))throw Error('Invalid record');const o={};for(const k of ['slug','revision','submission','receipt','submittedAt','archiveHash','archiveName','bundleFingerprint','changes','decision','approvedAt','approvalEvidence','rejection','failureNotes','attempts','paidAt','paymentEvidence','notes','conflict'])o[k]=typeof d[k]==='string'?d[k]:'';o.paid=d.paid===true;o.gates={};for(const [id]of gates)o.gates[id]=states.includes(d.gates?.[id])?d.gates[id]:'pending';return o;}
root.SubmissionCore={gates,states,validate,payout,normalize};if(typeof module!=='undefined')module.exports=root.SubmissionCore;
})(typeof window!=='undefined'?window:globalThis);
